<?php
declare(strict_types=1);
namespace RetroWEB\Infrastructure\Persistence;

final class TrafficLimiter
{
    private \SQLite3 $db;
public function __construct(private string $path){$dir=dirname($path);if(!is_dir($dir))mkdir($dir,0700,true);$lock=fopen($path.'.init.lock','c');if($lock===false||!flock($lock,LOCK_EX))throw new \RuntimeException('Unable to initialise traffic database');try{$this->db=new \SQLite3($path);$this->db->enableExceptions(true);$this->db->busyTimeout(5000);$this->db->exec('PRAGMA journal_mode=WAL');$this->db->exec('PRAGMA synchronous=NORMAL');$this->db->exec('CREATE TABLE IF NOT EXISTS requests (client TEXT NOT NULL, occurred INTEGER NOT NULL)');$this->db->exec('CREATE INDEX IF NOT EXISTS requests_client_time ON requests(client,occurred)');$this->db->exec('CREATE TABLE IF NOT EXISTS traffic (client TEXT NOT NULL, day TEXT NOT NULL, bytes INTEGER NOT NULL, PRIMARY KEY(client,day))');$this->db->exec('CREATE TABLE IF NOT EXISTS blocked_clients (client TEXT PRIMARY KEY, blocked_at INTEGER NOT NULL)');}finally{flock($lock,LOCK_UN);fclose($lock);}}
public function allow(string $client,int $now,int $limit=30,int $window=60,int$globalLimit=0):bool{$this->db->exec('BEGIN IMMEDIATE');try{if($this->isBlocked($client)){$this->db->exec('COMMIT');return false;}$cut=$now-$window;$stmt=$this->db->prepare('DELETE FROM requests WHERE occurred < :cut');$stmt->bindValue(':cut',$cut,SQLITE3_INTEGER);$stmt->execute();$stmt=$this->db->prepare('SELECT COUNT(*) FROM requests WHERE client=:client');$stmt->bindValue(':client',$client,SQLITE3_TEXT);$count=(int)$stmt->execute()->fetchArray(SQLITE3_NUM)[0];$global=0;if($globalLimit>0)$global=(int)$this->db->querySingle('SELECT COUNT(*) FROM requests');if(!AbuseEscalation::check($this->db,$client,$now,$count>=$limit,dirname($this->path))||$globalLimit>0&&$global>=$globalLimit){$this->db->exec('COMMIT');return false;}$this->insertRequest($client,$now);$this->db->exec('COMMIT');return true;}catch(\Throwable$e){$this->db->exec('ROLLBACK');throw$e;}}
    public function block(string$client,int$now):void{$this->db->exec('CREATE TABLE IF NOT EXISTS permanent_ip_clients(client TEXT PRIMARY KEY)');$q=$this->db->prepare('INSERT OR IGNORE INTO permanent_ip_clients VALUES(:client)');$q->bindValue(':client',$client);$q->execute();$stmt=$this->db->prepare('INSERT INTO blocked_clients(client,blocked_at) VALUES(:client,:now) ON CONFLICT(client) DO UPDATE SET blocked_at=excluded.blocked_at');$stmt->bindValue(':client',$client,SQLITE3_TEXT);$stmt->bindValue(':now',$now,SQLITE3_INTEGER);$stmt->execute();}
    public function unblock(string$client):void{$this->db->exec('CREATE TABLE IF NOT EXISTS permanent_ip_clients(client TEXT PRIMARY KEY)');$q=$this->db->prepare('DELETE FROM permanent_ip_clients WHERE client=:client');$q->bindValue(':client',$client);$q->execute();$stmt=$this->db->prepare('DELETE FROM blocked_clients WHERE client=:client');$stmt->bindValue(':client',$client,SQLITE3_TEXT);$stmt->execute();}
    public function record(string $client,int $bytes,int $now,int $clientDaily=10737418240,int $globalDaily=536870912000,int$globalMonthly=10995116277760):bool{$client=preg_replace('/:(?:page|image)$/','',$client);$day=gmdate('Y-m-d',$now);$month=substr($day,0,7);$this->db->exec('BEGIN IMMEDIATE');try{$clientUsed=$this->sum($day,$client);$globalUsed=$this->sum($day,null);$monthlyUsed=$this->sumMonth($month);if($clientUsed+$bytes>$clientDaily||$globalUsed+$bytes>$globalDaily||$monthlyUsed+$bytes>$globalMonthly){$this->db->exec('ROLLBACK');return false;}$stmt=$this->db->prepare('INSERT INTO traffic(client,day,bytes) VALUES(:client,:day,:bytes) ON CONFLICT(client,day) DO UPDATE SET bytes=bytes+excluded.bytes');$stmt->bindValue(':client',$client,SQLITE3_TEXT);$stmt->bindValue(':day',$day,SQLITE3_TEXT);$stmt->bindValue(':bytes',$bytes,SQLITE3_INTEGER);$stmt->execute();$this->db->exec('COMMIT');return true;}catch(\Throwable $e){$this->db->exec('ROLLBACK');throw $e;}}
    public function prune(int$now,int$retentionDays=7):int{$retentionDays=max(1,$retentionDays);$cutoff=gmdate('Y-m-d',$now-$retentionDays*86400);$this->db->exec('BEGIN IMMEDIATE');try{$requests=$this->db->prepare('DELETE FROM requests WHERE occurred < :cut');$requests->bindValue(':cut',$now-3600,SQLITE3_INTEGER);$requests->execute();$traffic=$this->db->prepare('DELETE FROM traffic WHERE day < :day');$traffic->bindValue(':day',$cutoff,SQLITE3_TEXT);$traffic->execute();$removed=$this->db->changes();$this->db->exec('COMMIT');return$removed;}catch(\Throwable$e){$this->db->exec('ROLLBACK');throw$e;}}
    private function sum(string $day,?string $client):int{$sql='SELECT COALESCE(SUM(bytes),0) FROM traffic WHERE day=:day'.($client!==null?' AND client=:client':'');$stmt=$this->db->prepare($sql);$stmt->bindValue(':day',$day,SQLITE3_TEXT);if($client!==null)$stmt->bindValue(':client',$client,SQLITE3_TEXT);return(int)$stmt->execute()->fetchArray(SQLITE3_NUM)[0];}
    private function sumMonth(string$month):int{$stmt=$this->db->prepare('SELECT COALESCE(SUM(bytes),0) FROM traffic WHERE day LIKE :month');$stmt->bindValue(':month',$month.'-%',SQLITE3_TEXT);return(int)$stmt->execute()->fetchArray(SQLITE3_NUM)[0];}
    private function insertRequest(string$client,int$now):void{$stmt=$this->db->prepare('INSERT INTO requests(client,occurred) VALUES(:client,:now)');$stmt->bindValue(':client',$client,SQLITE3_TEXT);$stmt->bindValue(':now',$now,SQLITE3_INTEGER);$stmt->execute();}
    private function isBlocked(string$client):bool{$stmt=$this->db->prepare('SELECT 1 FROM blocked_clients WHERE client=:client');$stmt->bindValue(':client',$client,SQLITE3_TEXT);return(bool)$stmt->execute()->fetchArray(SQLITE3_NUM);}
}
